"""Bounded exploratory search (NOT a proof).  Sources: subsemigroups of P(C,D) generated by four
letters whose twisted B5^1 coordinates realize the SN failure (u0,x,1,u1), plus optionally one chosen
inverse of each letter.  D=M[Z_k;I,L;P] with trivial action on C=B5^1.  Filters: regular, every
idempotent actor fibre SN.  Pattern: abcda!=abcacda with prefix conditions modulo nu'."""
import random,json,sys,time
from itertools import product
def b5(a,b):
 if a==5:return b
 if b==5:return a
 if b==0:return 0
 if a==0:return b+2 if b in (1,2) else b
 if a in (1,2):return a if b in (1,2) else b
 return a if b in (1,2) else b
class Host:
 def __init__(s,k,I,L,P):
  s.k,s.I,s.L,s.P=k,I,L,P
  s.D=[(i,g,l) for i in range(I) for g in range(k) for l in range(L)]
  s.H=[(b,d) for b in range(6) for d in s.D];s.ix={h:n for n,h in enumerate(s.H)}
  s.memo={}
 def dm(s,x,y):
  i,g,l=x;j,h,m=y;return(i,(g+s.P[l][j]+h)%s.k,m)
 def mul(s,x,y):
  key=(x,y)
  if key in s.memo:return s.memo[key]
  (b,dx),(c,dy)=s.H[x],s.H[y];z=s.ix[(b5(b,c),s.dm(dx,dy))];s.memo[key]=z;return z
def closure(h,gens,cap=400):
 S=set(gens);fr=list(gens)
 while fr:
  new=[]
  for x in fr:
   for y in list(S):
    for z in (h.mul(x,y),h.mul(y,x)):
     if z not in S:
      S.add(z);new.append(z)
      if len(S)>cap:return None
  fr=new
 return sorted(S)
def analyse(h,S):
 m=h.mul;E=[x for x in S if m(x,x)==x];Es=set(E)
 for x in S:
  if not any(m(m(x,y),x)==x and m(m(y,x),y)==y for y in S):return None,'nonregular'
 fib={}
 for e in E:fib.setdefault(h.H[e][1],[]).append(e)
 for F in fib.values():
  for a,b,c,d in product(F,repeat=4):
   if m(m(m(m(a,b),c),d),a)!=m(m(m(m(m(m(a,b),c),a),c),d),a):return None,'badfibre'
 par={x:x for x in S}
 def root(x):
  while par[x]!=x:par[x]=par[par[x]];x=par[x]
  return x
 todo=[(e,f) for e in E for f in E if e!=f and m(e,f)==m(f,e)==e]
 while todo:
  a,b=todo.pop();ra,rb=root(a),root(b)
  if ra!=rb:
   par[rb]=ra
   for z in S:todo.append((m(a,z),m(b,z)));todo.append((m(z,a),m(z,b)))
 return {x:root(x) for x in S},'ok'
def pattern(h,S,cls,seed4=None):
 m=h.mul
 quads=[seed4] if seed4 else None
 it=quads if quads else ((a,b,c,d) for a,b,c in product(S,repeat=3) for d in S)
 for a,b,c,d in it:
  abc=m(m(a,b),c)
  if cls[m(abc,a)]!=cls[a] or cls[abc]!=cls[m(a,c)]:continue
  u=m(m(abc,d),a)
  if cls[u]!=cls[a]:continue
  v=m(m(m(m(abc,a),c),d),a)
  if u!=v:return (a,b,c,d,u,v)
 return None
if __name__=='__main__':
 seed=int(sys.argv[1]);budget=float(sys.argv[2]);random.seed(seed)
 t0=time.time();stats={};hits=0
 shapes=[(3,2,2),(2,3,3),(3,3,2),(4,2,2),(2,2,3)]
 while time.time()-t0<budget:
  k,I,L=random.choice(shapes)
  P=[[random.randrange(k) for _ in range(I)] for _ in range(L)]
  P[0]=[0]*I
  for r in P:r[0]=0
  if all(P[l][i]==0 for l in range(L) for i in range(I)):continue
  h=Host(k,I,L,P);D=h.D
  d1,d2,d3,d4=(random.choice(D) for _ in range(4))
  # enforce prefix conditions in D by choosing labels: test and skip otherwise
  dmul=lambda *xs:__import__('functools').reduce(h.dm,xs)
  if not(dmul(d1,d2,d3,d1)==d1 and dmul(d1,d2,d3)==dmul(d1,d3) and dmul(d1,d2,d3,d4,d1)==d1):continue
  gens=[h.ix[(1,d1)],h.ix[(0,d2)],h.ix[(5,d3)],h.ix[(2,d4)]]
  key=str((k,I,L));st=stats.setdefault(key,{'tried':0,'closed':0,'regular_SN':0,'hits':0});st['tried']+=1
  # optionally add a random inverse for each generator inside the host
  if random.random()<0.6:
   extra=[]
   for g in gens:
    inv=[y for y in range(len(h.H)) if h.mul(h.mul(g,y),g)==g and h.mul(h.mul(y,g),y)==y]
    extra.append(random.choice(inv))
   gens=gens+extra
  S=closure(h,gens)
  if S is None:continue
  st['closed']+=1
  cls,status=analyse(h,S)
  if status!='ok':continue
  st['regular_SN']+=1
  w=pattern(h,S,cls,seed4=tuple(gens[:4])) or (pattern(h,S,cls) if len(S)<=45 else None)
  if w:
   st['hits']+=1;hits+=1
   print(json.dumps({'shape':key,'P':P,'size':len(S),'gens':[str(h.H[g]) for g in gens],'witness':[str(h.H[z]) for z in w]}));sys.stdout.flush()
   if hits>=3:break
 print(json.dumps({'seed':seed,'seconds':round(time.time()-t0,1),'stats':stats,'hits':hits}))
